mapper.select:
SELECT tenant_id AS tenantId,result_id AS resultId FROM join_task_approval
WHERE stage IN (1,2,3,4,5,6) AND next_execute_at <= #{now}
ORDER BY next_execute_at,result_id LIMIT 20

mapper.update:
UPDATE join_task_result SET dispatch_state='APPROVAL',next_execute_at=NULL,updated_at=#{now}
WHERE id=#{row.id} AND status='PENDING' AND dispatch_state='SUBMITTED'
  AND command_id=#{row.commandId} AND attempt_no=#{row.attemptNo}

UPDATE join_task_result SET dispatch_state='SUBMITTED'
WHERE id=#{row.id} AND status='PENDING' AND dispatch_state='APPROVAL'
  AND command_id=#{row.commandId} AND attempt_no=#{row.attemptNo}
